// MT2009_PLUS_DS_GLOBAL_TABLE_V1 (load): M2_BONUS_MODE=global (the owner, 15 October 2026) - the alchemy has the
// default bonuses too (Owsap's table = the GF client's, dragon_soul_table.global.txt, made at image build beside
// dragon_soul_table.mt2009.txt; server-patches/bonusyglobal/README.md). The mode comes from the environment, as the
// migrator reads it (apply.sh) - a core loads the table before the event flags arrive. The other tables stay
// loaded: a stone keeps the bonuses it was made with, and a strength refine rescales them from the table that
// has them (DSStoneTable) instead of turning them into the current table's.
static std::vector<DragonSoulTable*> s_vecDSOtherTables;

static bool DSBonusModeGlobal()
{
	const char* p = getenv("M2_BONUS_MODE");
	std::string s;
	for (; p && *p; ++p)
		if (!isspace((unsigned char) *p))
			s += (char) tolower((unsigned char) *p);
	return s == "global" || s == "globalny" || s == "1";
}

static bool DSFileReadable(const std::string& path)
{
	FILE* fp = fopen(path.c_str(), "rb");
	if (!fp)
		return false;
	fclose(fp);
	return true;
}

// Does every bonus of the stone belong to this table: a basic slot holds the table's basic bonus of that slot,
// an additional slot one of its additional bonuses (an empty slot fits any table).
static bool DSStoneFitsTable(DragonSoulTable* pTable, LPITEM pDS, BYTE ds_type, BYTE grade_idx)
{
	DragonSoulTable::TVecApplys vec_basic, vec_add;
	int basic_num, add_min, add_max;
	if (!pTable || !pTable->GetBasicApplys(ds_type, vec_basic) || !pTable->GetAdditionalApplys(ds_type, vec_add)
			|| !pTable->GetApplyNumSettings(ds_type, grade_idx, basic_num, add_min, add_max))
		return false;
	const int n = MIN(basic_num, (int) vec_basic.size());
	for (int i = 0; i < ITEM_ATTRIBUTE_MAX_NUM; ++i)
	{
		const BYTE bType = pDS->GetAttributeType(i);
		if (POINT_NONE == bType)
			continue;
		if (i < DRAGON_SOUL_ADDITIONAL_ATTR_START_IDX)
		{
			if (i >= n || vec_basic[i].apply_type != bType)
				return false;
			continue;
		}
		bool found = false;
		for (size_t j = 0; j < vec_add.size() && !found; ++j)
			found = (vec_add[j].apply_type == bType);
		if (!found)
			return false;
	}
	return true;
}

// The table a stone's bonuses came from: the current one when they fit it (also a stone with no bonus yet),
// else the first other one they fit, else the current one.
static DragonSoulTable* DSStoneTable(DragonSoulTable* pCurrent, LPITEM pDS, BYTE ds_type, BYTE grade_idx)
{
	if (DSStoneFitsTable(pCurrent, pDS, ds_type, grade_idx))
		return pCurrent;
	for (size_t i = 0; i < s_vecDSOtherTables.size(); ++i)
		if (DSStoneFitsTable(s_vecDSOtherTables[i], pDS, ds_type, grade_idx))
		{
			sys_log(0, "[DS_ATTR] stone vnum=%u id=%u keeps the bonuses of its own table (#%u)",
				pDS->GetVnum(), pDS->GetID(), (unsigned) i);
			return s_vecDSOtherTables[i];
		}
	return pCurrent;
}

bool DSManager::ReadDragonSoulTableFile(const char * c_pszFileName)
{
	std::string dir(c_pszFileName);
	const size_t slash = dir.find_last_of('/');
	dir = (std::string::npos == slash) ? std::string() : dir.substr(0, slash + 1);
	const std::string liveFile(c_pszFileName);
	const std::string globalFile = dir + "dragon_soul_table.global.txt";
	const std::string mt2009File = dir + "dragon_soul_table.mt2009.txt";

	std::string mainFile = liveFile;
	if (DSBonusModeGlobal())
	{
		if (DSFileReadable(globalFile))
			mainFile = globalFile;
		else
			sys_err("DragonSoulTable: M2_BONUS_MODE=global but no %s - the alchemy keeps %s", globalFile.c_str(), liveFile.c_str());
	}

	m_pTable = new DragonSoulTable();
	if (!m_pTable->ReadDragonSoulTableFile(mainFile.c_str()))
	{
		if (mainFile == liveFile)
			return false;
		sys_err("DragonSoulTable: %s could not be read - the alchemy keeps %s", mainFile.c_str(), liveFile.c_str());
		mainFile = liveFile;
		m_pTable = new DragonSoulTable();
		if (!m_pTable->ReadDragonSoulTableFile(mainFile.c_str()))
			return false;
	}
	sys_log(0, "DragonSoulTable: M2_BONUS_MODE=%s - the alchemy table is %s", DSBonusModeGlobal() ? "global" : "mt2009", mainFile.c_str());

	s_vecDSOtherTables.clear();
	const std::string others[] = { liveFile, mt2009File, globalFile };
	for (size_t i = 0; i < sizeof(others) / sizeof(others[0]); ++i)
	{
		if (others[i] == mainFile || !DSFileReadable(others[i]))
			continue;
		DragonSoulTable* pOther = new DragonSoulTable();
		if (pOther->ReadDragonSoulTableFile(others[i].c_str()))
			s_vecDSOtherTables.push_back(pOther);
		else
			sys_err("DragonSoulTable: %s (the other mode's table) could not be read - its stones rescale from %s",
				others[i].c_str(), mainFile.c_str());
	}
	return true;
}

